import{_ as d,o as r,c as a,a3 as o}from"./chunks/framework.bvEHUNtb.js";const b=JSON.parse('{"title":"象数易理篇之一：数理地基","description":"从卦数、五行、卦气到干支，建立梅花易数的基础坐标。","frontmatter":{"title":"象数易理篇之一：数理地基","description":"从卦数、五行、卦气到干支，建立梅花易数的基础坐标。","category":"学习计划 · 第一阶段"},"headers":[],"relativePath":"yijing/meihua-yishu/xiang-shu-li/number-foundation.md","filePath":"yijing/meihua-yishu/xiang-shu-li/number-foundation.md","lastUpdated":1786982540000}'),n={name:"yijing/meihua-yishu/xiang-shu-li/number-foundation.md"};function e(s,t,i,l,h,p){return r(),a("div",null,[...t[0]||(t[0]=[o(`<blockquote><p>周易卦数 → 五行生克 → 八宫五行 → 卦气旺衰 → 十天干 → 十二地支 → 八卦象例</p></blockquote><h2 id="📜-原文" tabindex="-1">📜 原文 <a class="header-anchor" href="#📜-原文" aria-label="Permalink to &quot;📜 原文&quot;">​</a></h2><p><strong>周易卦数</strong><br> 干，一；兑，二；离，三；震，四；巽，五；坎，六；艮，七；坤，八。</p><p><strong>五行生克</strong><br> 金生水，水生木，木生火，火生土，土生金；<br> 金克木，木克土，土克水，水克火，火克金。</p><p><strong>八宫所属五行</strong><br> 干、兑，金；坤、艮，土；震、巽，木；坎，水；离，火。</p><p><strong>卦气旺</strong><br> 震、巽木旺于春，离火旺于夏，干、兑金旺于秋，坎水旺于冬，坤、艮土旺于辰戌丑未月。</p><p><strong>卦气衰</strong><br> 春坤、艮，夏干、兑，秋震、巽，冬离，辰戌丑未坎。</p><p><strong>十天干</strong><br> 甲乙东方木，丙丁南方火，戊己中央土，庚辛西方金，壬癸北方水。</p><p><strong>十二地支</strong><br> 子水鼠，丑土牛，寅木虎，卯木兔，辰土龙，巳火蛇，午火马，未土羊，申猴金，酉金鸡，戌土犬，亥水猪。</p><p><strong>八卦象例</strong><br> 乾三连，坤六断，震仰盂，艮覆碗，离中虚，坎中满，兑上缺，巽下断。</p><hr><h2 id="🔤-注音与字词" tabindex="-1">🔤 注音与字词 <a class="header-anchor" href="#🔤-注音与字词" aria-label="Permalink to &quot;🔤 注音与字词&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字词</th><th>注音</th><th>释义</th></tr></thead><tbody><tr><td>乾</td><td>qián</td><td>八卦之首，天，阳</td></tr><tr><td>兑</td><td>duì</td><td>泽，喜悦</td></tr><tr><td>巽</td><td>xùn</td><td>风，顺</td></tr><tr><td>坎</td><td>kǎn</td><td>水，险</td></tr><tr><td>艮</td><td>gèn</td><td>山，止</td></tr><tr><td>辰戌丑未月</td><td>—</td><td>四季末月，即每季最后一个月，属土</td></tr><tr><td>仰盂</td><td>yǎng yú</td><td>盂（盛水器）口朝上，震卦下实上虚之象</td></tr><tr><td>覆碗</td><td>fù wǎn</td><td>碗口朝下扣着，艮卦上实下虚之象</td></tr><tr><td>离中虚</td><td>—</td><td>离卦中爻为阴，中间空虚</td></tr><tr><td>坎中满</td><td>—</td><td>坎卦中爻为阳，中间充实</td></tr><tr><td>兑上缺</td><td>—</td><td>兑卦上爻为阴，顶部有缺口</td></tr><tr><td>巽下断</td><td>—</td><td>巽卦初爻为阴，底部断开</td></tr></tbody></table><hr><h2 id="📖-白话译文" tabindex="-1">📖 白话译文 <a class="header-anchor" href="#📖-白话译文" aria-label="Permalink to &quot;📖 白话译文&quot;">​</a></h2><p><strong>周易卦数</strong><br> 八卦各有其数：乾一、兑二、离三、震四、巽五、坎六、艮七、坤八。</p><p><strong>五行生克</strong><br> 相生：金生水，水生木，木生火，火生土，土生金。<br> 相克：金克木，木克土，土克水，水克火，火克金。</p><p><strong>八宫所属五行</strong><br> 乾、兑属金；坤、艮属土；震、巽属木；坎属水；离属火。</p><p><strong>卦气旺</strong><br> 震、巽（木）旺于春季；离（火）旺于夏季；乾、兑（金）旺于秋季；坎（水）旺于冬季；坤、艮（土）旺于辰、戌、丑、未月（四季末月）。</p><p><strong>卦气衰</strong><br> 春季坤、艮衰；夏季乾、兑衰；秋季震、巽衰；冬季离衰；辰戌丑未月坎衰。</p><p><strong>十天干</strong><br> 甲、乙属东方木；丙、丁属南方火；戊、己属中央土；庚、辛属西方金；壬、癸属北方水。</p><p><strong>十二地支</strong><br> 子水（鼠）、丑土（牛）、寅木（虎）、卯木（兔）、辰土（龙）、巳火（蛇）、午火（马）、未土（羊）、申金（猴）、酉金（鸡）、戌土（犬）、亥水（猪）。</p><p><strong>八卦象例</strong><br> 乾三连（三爻皆阳，三条实线）；坤六断（三爻皆阴，六段虚线）；震仰盂（下实上虚，如仰放的盂）；艮覆碗（上实下虚，如扣置的碗）；离中虚（中爻为阴，中间空）；坎中满（中爻为阳，中间实）；兑上缺（上爻为阴，顶部缺）；巽下断（初爻为阴，底部断）。</p><hr><h2 id="🧭-义理解析" tabindex="-1">🧭 义理解析 <a class="header-anchor" href="#🧭-义理解析" aria-label="Permalink to &quot;🧭 义理解析&quot;">​</a></h2><h3 id="一、卦数-这套数字从哪里来" tabindex="-1">一、卦数：这套数字从哪里来？ <a class="header-anchor" href="#一、卦数-这套数字从哪里来" aria-label="Permalink to &quot;一、卦数：这套数字从哪里来？&quot;">​</a></h3><p>乾一至坤八，这是<strong>先天八卦序数</strong>，出自邵雍的先天易学体系。</p><p>与我们熟悉的「洛书数」（坎一、坤二……）不同，这里用的是先天卦序：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>乾一 兑二 离三 震四 巽五 坎六 艮七 坤八</span></span></code></pre></div><p>这个数字系统是梅花易数起卦的根基——后面所有的「以八除取余」，用的就是这套数。</p><p>记忆口诀：<strong>一乾二兑三离四震，五巽六坎七艮八坤</strong></p><h3 id="二、五行生克-最小的宇宙模型" tabindex="-1">二、五行生克：最小的宇宙模型 <a class="header-anchor" href="#二、五行生克-最小的宇宙模型" aria-label="Permalink to &quot;二、五行生克：最小的宇宙模型&quot;">​</a></h3><p>五行生克是中国传统思想里最精简的<strong>动态关系模型</strong>：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>相生（顺时针）：木→火→土→金→水→木</span></span>
<span class="line"><span>相克（隔一位）：木→土→水→火→金→木</span></span></code></pre></div><p>在梅花易数里，五行生克是判断吉凶的核心工具：</p><ul><li><strong>生体为吉</strong>（滋养我）</li><li><strong>克体为凶</strong>（压制我）</li><li><strong>比和为吉</strong>（同类相助）</li><li><strong>体生用为耗</strong>（我去滋养别人，有损耗）</li></ul><h3 id="三、八宫五行-卦与五行的对应" tabindex="-1">三、八宫五行：卦与五行的对应 <a class="header-anchor" href="#三、八宫五行-卦与五行的对应" aria-label="Permalink to &quot;三、八宫五行：卦与五行的对应&quot;">​</a></h3><table tabindex="0"><thead><tr><th>五行</th><th>对应卦</th><th>方位</th><th>季节</th></tr></thead><tbody><tr><td>金</td><td>乾、兑</td><td>西、西北</td><td>秋</td></tr><tr><td>木</td><td>震、巽</td><td>东、东南</td><td>春</td></tr><tr><td>水</td><td>坎</td><td>北</td><td>冬</td></tr><tr><td>火</td><td>离</td><td>南</td><td>夏</td></tr><tr><td>土</td><td>坤、艮</td><td>西南、东北</td><td>四季末月</td></tr></tbody></table><p><strong>土为什么旺于四季末月？</strong><br> 中国传统认为土居中央，寄旺于四季，每季最后18天（辰戌丑未月）是土气最旺的时候。这是「土主长养，无处不在」的象。</p><h3 id="四、卦气旺衰-时间维度的生命力" tabindex="-1">四、卦气旺衰：时间维度的生命力 <a class="header-anchor" href="#四、卦气旺衰-时间维度的生命力" aria-label="Permalink to &quot;四、卦气旺衰：时间维度的生命力&quot;">​</a></h3><p>旺衰表的逻辑非常简洁：<strong>当令则旺，被克则衰。</strong></p><table tabindex="0"><thead><tr><th>季节</th><th>当令（旺）</th><th>被克（衰）</th></tr></thead><tbody><tr><td>春（木旺）</td><td>震、巽</td><td>坤、艮（木克土）</td></tr><tr><td>夏（火旺）</td><td>离</td><td>乾、兑（火克金）</td></tr><tr><td>秋（金旺）</td><td>乾、兑</td><td>震、巽（金克木）</td></tr><tr><td>冬（水旺）</td><td>坎</td><td>离（水克火）</td></tr><tr><td>四季末（土旺）</td><td>坤、艮</td><td>坎（土克水）</td></tr></tbody></table><p>这张表后面会频繁用到——体卦旺则吉，体卦衰则凶，是断卦的基本盘。</p><h3 id="五、天干地支-时间的坐标系" tabindex="-1">五、天干地支：时间的坐标系 <a class="header-anchor" href="#五、天干地支-时间的坐标系" aria-label="Permalink to &quot;五、天干地支：时间的坐标系&quot;">​</a></h3><p>天干地支在梅花易数里主要用于两个地方：</p><ol><li><strong>年月日时起卦</strong>（子年=1，丑年=2……）</li><li><strong>判断克应时间</strong>（生体之卦气旺于何日，即为吉应之期）</li></ol><p>十二地支配五行，有一个特别值得注意的地方：</p><blockquote><p>土占了六个地支中的<strong>五个</strong>：丑、辰、未、戌（四季末月）+ 戊己（天干）</p></blockquote><p>土是最多的，因为土是承载一切的基础——这是象，不只是规则。</p><h3 id="六、八卦象例-用身体记住卦形" tabindex="-1">六、八卦象例：用身体记住卦形 <a class="header-anchor" href="#六、八卦象例-用身体记住卦形" aria-label="Permalink to &quot;六、八卦象例：用身体记住卦形&quot;">​</a></h3><p>这八句口诀，是用<strong>形象</strong>来记卦形，而非用文字：</p><table tabindex="0"><thead><tr><th>卦</th><th>口诀</th><th>象</th></tr></thead><tbody><tr><td>乾 ☰</td><td>三连</td><td>天，纯阳，刚健</td></tr><tr><td>坤 ☷</td><td>六断</td><td>地，纯阴，柔顺</td></tr><tr><td>震 ☳</td><td>仰盂</td><td>雷，下实上虚，动而上发</td></tr><tr><td>艮 ☶</td><td>覆碗</td><td>山，上实下虚，止而不动</td></tr><tr><td>离 ☲</td><td>中虚</td><td>火，外实中空，文明之象</td></tr><tr><td>坎 ☵</td><td>中满</td><td>水，外虚中实，险陷之象</td></tr><tr><td>兑 ☱</td><td>上缺</td><td>泽，上有缺口，喜悦开口</td></tr><tr><td>巽 ☴</td><td>下断</td><td>风，下有缺口，入而渗透</td></tr></tbody></table><p>离与坎互为镜像——一个中虚，一个中满；一个是火（外明内空），一个是水（外柔内刚）。这是《易》里最深的一对：<strong>外表与内在，往往相反</strong>。</p><hr><h2 id="🌀-象的感悟" tabindex="-1">🌀 象的感悟 <a class="header-anchor" href="#🌀-象的感悟" aria-label="Permalink to &quot;🌀 象的感悟&quot;">​</a></h2><h3 id="关于五行" tabindex="-1">关于五行 <a class="header-anchor" href="#关于五行" aria-label="Permalink to &quot;关于五行&quot;">​</a></h3><p>五行生克，背起来是规则，感受起来是<strong>流动</strong>。</p><p>这些不是规定，是真实发生的事。木燃烧生火；火烧尽成灰成土；土里藏矿成金；金遇冷凝结水气；水滋润生木。</p><p>每一个「生」，都是一种给予，一种流向。<br> 每一个「克」，都是一种制约，一种边界。</p><p><strong>五行不是五个格子，是五种流动的状态。</strong></p><h3 id="关于卦气旺衰" tabindex="-1">关于卦气旺衰 <a class="header-anchor" href="#关于卦气旺衰" aria-label="Permalink to &quot;关于卦气旺衰&quot;">​</a></h3><p>春天，木气最盛。这时候震卦（雷）、巽卦（风）是最有力量的——春雷一声，万物惊醒；春风一过，草木萌发。这不是抽象的「旺」，是真实可感的生命力。</p><p>而这时候，坤、艮（土）是衰的——冬末春初，土地还冻着，还没有力量。木气太盛，土被压制。</p><p><strong>旺衰不是好坏，是时机。</strong> 同一个卦，春天衰，秋天旺。没有永远强的，也没有永远弱的。</p><h3 id="关于八卦象例" tabindex="-1">关于八卦象例 <a class="header-anchor" href="#关于八卦象例" aria-label="Permalink to &quot;关于八卦象例&quot;">​</a></h3><p>「坎中满」——坎是水，是险。但它中间是实的，是阳爻。外面看起来柔软、危险、流动，里面却是最坚实的。</p><p>这是水的象：<strong>表面顺从，内里有力</strong>。老子说「天下莫柔弱于水，而攻坚强者莫之能胜」，说的就是这个中满。</p><p>「离中虚」——离是火，是文明，是光。但它中间是空的，是阴爻。光最亮的地方，往往是空的——蜡烛的火焰中心是暗的，太阳的核心是空洞的。<strong>最明亮的，往往中间有一个空。</strong> 这是离的象。</p><p>坎与离，一个中满，一个中虚，互为镜像——这是《易》里藏着的最深的话。</p><hr><h2 id="📌-小结" tabindex="-1">📌 小结 <a class="header-anchor" href="#📌-小结" aria-label="Permalink to &quot;📌 小结&quot;">​</a></h2><p><strong>本节关键词</strong></p><ul><li>先天卦数：乾一兑二离三震四巽五坎六艮七坤八</li><li>五行：金木水火土，生克各有方向</li><li>八宫五行：乾兑金·坤艮土·震巽木·坎水·离火</li><li>卦气旺衰：当令则旺，被克则衰</li><li>天干地支：时间坐标，用于起卦与定期</li><li>八卦象例：用形象记卦形，不用死记</li></ul><p><strong>规律提炼</strong></p><ol><li>这一节是整本书的<strong>工具箱</strong>，后面每一个起卦、断卦，都要回来取工具</li><li>旺衰的判断，贯穿全书始终——体卦旺则有救，体卦衰则凶险</li><li>八卦象例不只是记忆口诀，每一句都是一个<strong>活的意象</strong></li></ol><p><strong>与前文呼应</strong></p><ul><li>序中说「先天之数」「后天之数」，这里的卦数（乾一至坤八）正是先天数的基础</li><li>序中「物之成毁有数」，这里开始建立那个「数」的具体系统</li></ul><hr><h2 id="❓-存疑" tabindex="-1">❓ 存疑 <a class="header-anchor" href="#❓-存疑" aria-label="Permalink to &quot;❓ 存疑&quot;">​</a></h2><blockquote><p><strong>❓****-002</strong>：十二地支中，「申」对应金，原文写「申猴金」，但天干「庚辛」也属金，两套系统的金在使用时如何区分优先级？待卷二体用生克篇中「克应之期」章节对照。</p></blockquote><blockquote><p><strong>❓****-003</strong>：「乾坤无互，互其变卦」——乾坤为何无互？从卦形看，乾三连、坤六断，去掉初爻和上爻后，中间四爻仍是纯阳或纯阴，互卦仍是乾或坤本身，等于没有变化。这是原因吗？待卷三变卦式章节印证。</p></blockquote>`,81)])])}const u=d(n,[["render",e]]);export{b as __pageData,u as default};
